from autore import Modulo,estratto
from tikz_base import scrivi,n,a,rect,linea
m=Modulo('M08','Analisi multivariata dei campioni','Geometria della PCA, partizioni e interpretazione geologica')
def p(t,s,**kw):m.pagina(t,s,**kw)
def d(i,b):return scrivi('M08',i,b)
m.sezione_nuova('Campioni, variabili e scale')
p('Ogni riga rappresenta un campione identificabile',
'''Una descrizione multivariata associa a ciascun campione un insieme di misure, le cui definizioni determinano quali somiglianze possano essere riconosciute. Il caso guida comprende novanta rocce sintetiche, generate in tre gruppi di trenta individui. Le otto colonne utilizzate combinano frazioni di ossidi, densità, granulometria e indici convenzionali di colore e presenza di fossili. L’identificativo resta associato alla riga, mentre l’etichetta litologica generatrice viene esclusa dal calcolo e recuperata soltanto per interpretare l’esperimento.''',formula=r'X=(x_{ij})\in\mathbb R^{90\times8}',tikz=d('D01',n(3.7,.3,'Matrice delle osservazioni')+''.join(rect(.8+j*.7,1.1+i*.65,1.45+j*.7,1.7+i*.65,'Quantum' if i==2 else 'Classical',18 if i==2 else 5) for i in range(5) for j in range(8))+n(3.7,5,'Una riga: un campione; otto misure.',w=6.7,size=11)),richiamo='Unità, scala e significato delle variabili precedono la scelta dell’algoritmo.',origine='M08:1–15')
p('Una distanza incorpora una scelta di rilevanza',
'''La distanza euclidea combina gli scostamenti coordinata per coordinata, attribuendo maggiore peso numerico alle colonne che variano su scale più ampie. Nel dataset, l’ampiezza della variabilità dipende sia dalle proprietà simulate sia dalle unità adottate: una conversione da millimetri a micrometri cambierebbe la distanza grezza pur lasciando invariata la proprietà fisica. La standardizzazione costituisce pertanto una scelta interpretativa, attraverso la quale una deviazione standard diviene l’unità di confronto in ogni colonna.''',formula=r'd(\mathbf x_i,\mathbf x_h)=\sqrt{\sum_{j=1}^p(x_{ij}-x_{hj})^2}',figura='M08/F01',didascalia='Dispersioni delle otto colonne nelle rispettive unità. La scala logaritmica rende leggibili ordini di grandezza diversi.',richiamo='La distanza grezza può cambiare con le unità, se le colonne vengono convertite in modo differente.',origine='M08:16–18,23–25')
p('Centrare e ridimensionare conservando i parametri',
'''La trasformazione z-score sottrae la media e divide per la deviazione standard, purché positiva. Le colonne risultanti hanno media nulla e varianza unitaria, mentre asimmetrie e dipendenze rimangono riconoscibili. Per collocare un nuovo campione si riutilizzano medie e scale originarie, poiché ricalcolarle modificherebbe il sistema di riferimento. Eventuali valori mancanti richiedono una procedura dichiarata prima delle distanze.''',formula=r'z_{ij}=\frac{x_{ij}-\bar x_j}{s_j},\quad s_j>0\\ z_{\mathrm{nuovo},j}=\frac{x_{\mathrm{nuovo},j}-\bar x_j}{s_j}',destra='Per SiO₂ e densità, due scarti pari a 10 punti percentuali e 0,3 g/cm³ hanno significati diversi. Dopo la divisione per le rispettive deviazioni standard diventano confrontabili rispetto alla variabilità del campione di riferimento.',richiamo='Le medie e le scale fanno parte dell’oggetto stimato e devono accompagnare il risultato.',origine='M08:19–25')
c=estratto('M08','matrice',"d <- read.csv('dati/rocce_simulate.csv')\nv <- c('SiO2','CaO','MgO','FeO',\n       'densita','grana_mm','colore','fossili')\nX <- as.matrix(d[v])\nstopifnot(!anyNA(X),all(apply(X,2,sd)>0))\nZ <- scale(X)\nmedie <- attr(Z,'scaled:center')\nscale <- attr(Z,'scaled:scale')\nhead(Z)")
p('La selezione esplicita protegge la matrice di analisi',
'''Selezionare le variabili per nome permette di escludere identificativi, etichette generatrici e colonne che derivano da altre misure. Il codice verifica completezza e variabilità positiva prima della standardizzazione, rendendo visibili due condizioni necessarie per il laboratorio. In un dataset reale, la scelta potrebbe richiedere trasformazioni di variabili fortemente asimmetriche, trattamento dei limiti di rilevabilità o una distanza adatta a caratteri qualitativi. Ogni modifica va motivata rispetto alla domanda sulla somiglianza dei campioni.''',codice=c,richiamo='Una matrice numerica formalmente valida può ancora contenere variabili scientificamente inappropriate.',origine='M08:10–15,21–23,97')

m.sezione_nuova('Ridondanza e composizioni')
p('Duplicare una variabile ne aumenta il peso implicito',
'''Due colonne molto correlate rappresentano in parte la stessa informazione. La loro inclusione simultanea nella distanza euclidea può quindi enfatizzare una proprietà rispetto alle altre, anche quando entrambe siano standardizzate. Se una colonna viene duplicata esattamente, il relativo scarto quadratico compare due volte. La scelta di pesi espliciti rende riconoscibile questa decisione, mentre l’esclusione di una misura ridondante può essere valutata attraverso un’analisi di sensibilità della partizione.''',formula=r'd_w^2(i,h)=\sum_j w_j(z_{ij}-z_{hj})^2,\qquad w_j\geq0',tikz=d('D02',rect(.4,.7,3.2,2.2)+n(1.8,1.45,'Proprietà A',w=2.5)+rect(4.2,.7,7,2.2,'Quantum')+n(5.6,1.45,'Proprietà B',w=2.5)+a(1.8,2.4,1.2,3.4)+a(1.8,2.4,3,3.4)+a(5.6,2.4,5.6,3.4,'Quantum')+n(1.2,4,r'$z_A$')+n(3,4,r'$z_A$')+n(5.6,4,r'$z_B$')+n(3.7,5.5,r'$d^2=2(\Delta z_A)^2+(\Delta z_B)^2$')),richiamo='L’equilibrio fra proprietà dipende anche dalla ridondanza delle colonne.',origine='M08:21,26–28,88')
p('Il vincolo di chiusura delle composizioni',
'''Quando le parti sommano a una costante, l’aumento di una quota impone una compensazione nelle altre. Il vincolo di chiusura introduce quindi una dipendenza che condiziona le correlazioni. Le quattro frazioni di ossidi del laboratorio rappresentano una parte della composizione, la cui somma viene completata dalla colonna resto. La PCA sulle otto misure combina proprietà di natura differente e conserva una finalità geometrica esplorativa.''',formula=r'\sum_{j=1}^D x_j=100,\quad x_j\geq0\\ \operatorname{Var}\!\left(\sum_jX_j\right)=0',tikz=d('D03',r'\draw[Classical,fill=Classical!5,line width=1pt] (3.7,.7)--(.8,5.3)--(6.6,5.3)--cycle;'+n(3.7,.35,'A')+n(.5,5.6,'B')+n(6.9,5.6,'C')+r'\fill[Quantum] (3.1,3.5) circle (2pt);'+n(3.7,4.5,'A + B + C = 1',w=4.8,size=11)+n(3.7,6,'Tre parti, due coordinate libere.',w=6.6,size=11)),richiamo='La composizione e il sottoinsieme di parti analizzato devono essere dichiarati.',origine='M08:29–30,33–35,102')
p('I log-rapporti descrivono relazioni fra parti positive',
'''Il logaritmo del rapporto fra parti positive rimane invariato quando tutte vengono moltiplicate per uno stesso fattore. La trasformazione centrata confronta ciascuna parte con la media geometrica. Le coordinate sommano a zero, per cui la covarianza è singolare e lo spazio ha dimensione D meno uno. Zeri strutturali, arrotondamenti e concentrazioni sotto il limite analitico richiedono trattamenti distinti.''',formula=r'\operatorname{clr}(\mathbf x)_j=\log\frac{x_j}{g(\mathbf x)},\qquad g(\mathbf x)=\left(\prod_{j=1}^D x_j\right)^{1/D}\\ \sum_j\operatorname{clr}(\mathbf x)_j=0',destra='La sostituzione uniforme degli zeri con una piccola costante modifica i rapporti, soprattutto per le parti meno abbondanti. Nel laboratorio principale si mantiene l’analisi esplorativa dichiarata; un’analisi composizionale richiede una definizione più precisa delle parti e del processo di misura.',richiamo='I rapporti richiedono positività e una scelta scientificamente motivata delle parti.',origine='M08:31–35,102')

m.sezione_nuova('Geometria delle componenti principali')
p('La direzione di massima varianza',
'''La PCA cerca direzioni di massima variabilità nella nuvola centrata. La proiezione di ciascun campione su un vettore unitario v è il prodotto scalare della sua riga con v; la varianza delle coordinate è una forma quadratica della covarianza. Il massimo corrisponde a un autovettore del maggiore autovalore. Le componenti successive impongono l’ortogonalità alle direzioni già individuate.''',formula=r'S=\frac{Z^\top Z}{n-1},\qquad\max_{\|\mathbf v\|=1}\mathbf v^\top S\mathbf v\\ S\mathbf v_k=\lambda_k\mathbf v_k,\quad\lambda_1\geq\cdots\geq\lambda_p',tikz=d('D04',a(.9,5.1,6.5,1.1)+a(2.5,.88,4.9,5.32,'Quantum')+r'\draw[Classical,dashed] (2.9,2.05)--(3.5324,3.2197);\fill[Ink] (2.9,2.05) circle (2pt);\fill[Classical] (3.5324,3.2197) circle (2pt);'+n(5.9,.6,r'$\mathbf v_1$')+n(5.9,5.6,r'$\mathbf v_2$')+n(2.1,1.65,r'$\mathbf z_i$')+n(2.4,4.6,'Proiezione sul primo asse',w=3.5,size=11)),richiamo='La PCA ottimizza la rappresentazione della varianza sulla scala prescelta.',origine='M08:36–39')
p('Autovettori, scores e valori singolari',
'''Riunendo gli autovettori nelle colonne di V si ottiene una rotazione ortogonale. Le coordinate dei campioni nel nuovo riferimento, dette scores, sono raccolte nella matrice T. La decomposizione ai valori singolari fornisce una via numericamente stabile per ricavare la stessa rappresentazione, poiché i quadrati dei valori singolari, divisi per n meno uno, coincidono con gli autovalori di S. Questa relazione permette una verifica algebrica del calcolo di prcomp.''',formula=r'Z=UDV^\top,\qquad T=ZV=UD\\ V^\top V=I,\quad\lambda_k=\frac{d_k^2}{n-1}',destra='Le righe di T corrispondono ai campioni; le righe di V alle variabili. Il nome rotation in R identifica V, mentre x contiene T e sdev contiene le radici degli autovalori.',richiamo='Scores e coefficienti della rotazione hanno ruoli diversi e dimensioni matriciali differenti.',origine='M08:37–39,47–48')
p('L’ortogonalità elimina la covarianza fra scores',
'''La covarianza delle coordinate principali è diagonale, come si ricava sostituendo la rotazione nella definizione di covarianza campionaria. Le componenti risultano quindi incorrelate nel campione utilizzato per costruirle. L’indipendenza probabilistica richiede condizioni ulteriori e non segue dalla sola ortogonalità; inoltre, nuovi campioni possono presentare covarianze residue quando la distribuzione differisce da quella di addestramento. La proprietà geometrica deve essere riferita alla matrice sulla quale la PCA è stata stimata.''',formula=r'\operatorname{Cov}(T)=V^\top S V=\operatorname{diag}(\lambda_1,\ldots,\lambda_p)',tikz=d('D05',n(3.7,.4,'Covarianza delle coordinate')+''.join(rect(1.9+j*.9,1.1+i*.9,2.75+j*.9,1.95+i*.9,'Classical' if i==j else 'Rule',25 if i==j else 4)+n(2.325+j*.9,1.525+i*.9,rf'$\lambda_{{{i+1}}}$' if i==j else '0',size=11) for i in range(4) for j in range(4))+n(3.7,5.6,'Diagonale: varianze; fuori diagonale: zero.',w=6.8,size=11)),richiamo='Incorrelazione e indipendenza esprimono proprietà differenti.',origine='M08:38')
p('Varianza conservata ed errore di ricostruzione',
'''La quota di una componente è il suo autovalore diviso per la somma degli autovalori. Conservando q componenti si ottiene una ricostruzione di rango q che minimizza l’errore quadratico nella scala analizzata. Gli autovalori esclusi quantificano la perdita, sebbene una quota elevata conservata possa ancora trascurare caratteristiche geologicamente rilevanti. La scelta di q dipende quindi anche dall’uso successivo delle coordinate.''',formula=r'Q_q=\frac{\sum_{k=1}^q\lambda_k}{\sum_{k=1}^p\lambda_k},\qquad\widehat Z_q=T_qV_q^\top\\ \|Z-\widehat Z_q\|_F^2=(n-1)\sum_{k>q}\lambda_k',figura='M08/F02',didascalia='Barre: quota di ogni componente. Linea viola: quota cumulata. Le percentuali sono calcolate dal dataset allegato.',richiamo='La varianza rappresentata riguarda la scala scelta e deve comparire sugli assi della PCA.',origine='M08:40,44–45,53')
p('Il piano principale rende visibile una proiezione',
'''Nel piano delle prime due componenti ogni punto corrisponde a un campione, del quale si conservano due coordinate delle otto disponibili. La distanza nel piano è sempre minore o uguale alla distanza completa nello spazio standardizzato, perché parte degli scarti può ricadere nelle componenti omesse. Il colore recupera le etichette generatrici soltanto dopo la stima. Una separazione visiva favorevole descrive il caso sintetico e deve essere valutata insieme alla quota di varianza rappresentata.''',formula=r'\sum_{k=1}^2(t_{ik}-t_{hk})^2\leq\|\mathbf z_i-\mathbf z_h\|^2',figura='M08/F03',didascalia='PCA sulle otto misure standardizzate. Le etichette litologiche sintetiche non entrano nella stima degli assi.',richiamo='Punti vicini in proiezione possono essere separati nelle componenti escluse.',origine='M08:41,43–45,101')
p('L’orientamento dell’asse è arbitrario',
'''Moltiplicando un autovettore per meno uno si ottiene un autovettore altrettanto valido, al quale corrispondono scores con segno invertito. Le distanze, le varianze e la ricostruzione rimangono invariate, purché l’inversione venga applicata congiuntamente ai coefficienti e alle coordinate. Con autovalori coincidenti può variare anche la scelta degli assi entro il sottospazio. L’interpretazione riguarda le relazioni fra variabili e campioni, poiché il segno isolato è arbitrario.''',formula=r'(\mathbf t_k,\mathbf v_k)\mapsto(-\mathbf t_k,-\mathbf v_k)\\ \mathbf t_k\mathbf v_k^\top=(-\mathbf t_k)(-\mathbf v_k)^\top',tikz=d('D06',a(.6,2,6.8,2)+a(6.8,4.3,.6,4.3,'Quantum')+n(1,1.3,'−')+n(6.4,1.3,'+')+n(1,5,'+')+n(6.4,5,'−')+''.join(rf'\fill[Ink] ({x},2) circle (2pt);\fill[Ink] ({x},4.3) circle (2pt);' for x in [1.8,2.6,4.4,5.7])+n(3.7,3.15,'Stesse relazioni, orientamento invertito.',w=6.8,size=11)),richiamo='Le verifiche fra implementazioni devono ammettere inversioni di segno e sottospazi equivalenti.',origine='M08:42,54–55')

m.sezione_nuova('Interpretazione e calcolo della PCA')
p('I coefficienti descrivono come si costruisce un asse',
'''Ogni score è una combinazione lineare delle variabili centrate e ridimensionate, i cui pesi sono gli elementi dell’autovettore. Coefficienti dello stesso segno indicano contributi concordi alla componente, mentre segni opposti descrivono un contrasto fra proprietà. Il nome attribuito all’asse deve essere fondato sull’insieme dei pesi e sulle definizioni delle misure. Tornare ai campioni estremi e ai loro valori fisici permette di verificare se una denominazione, per esempio relativa alla composizione mafica, sia sostenibile.''',formula=r't_{ik}=\sum_j z_{ij}v_{jk},\qquad\sum_jv_{jk}^2=1',figura='M08/F04',didascalia='Coefficienti di PC1 e PC2.',richiamo='Il nome di una componente è un’interpretazione motivata dei coefficienti e dei campioni.',origine='M08:47–49,52,54–55')
p('Coefficienti e correlazioni richiedono scale distinte',
'''Per variabili standardizzate, la correlazione fra la variabile j e la componente k è il coefficiente della rotazione moltiplicato per la radice del relativo autovalore. Coefficienti e correlazioni rappresentano quindi quantità differenti. Il quadrato della correlazione misura la frazione di varianza ricostruita dalla componente; la somma sulle componenti conservate valuta la qualità della rappresentazione. Gli angoli richiedono questa parametrizzazione e una proiezione adeguata.''',formula=r'\operatorname{Cor}(Z_j,T_k)=\sqrt{\lambda_k}\,v_{jk}\\ R^2_{j,q}=\sum_{k=1}^q\lambda_kv_{jk}^2\leq1',destra='Una variabile può avere un peso relativamente elevato in una componente poco variabile e risultare comunque mal rappresentata nel piano. Per un campione, la quota di norma conservata è invece la somma dei primi q scores al quadrato divisa per la norma quadratica della sua riga standardizzata.',richiamo='La qualità della proiezione deve essere valutata per le variabili e per i campioni di interesse.',origine='M08:48–53')
c=estratto('M08','pca',"d <- read.csv('dati/rocce_simulate.csv')\nv <- c('SiO2','CaO','MgO','FeO',\n       'densita','grana_mm','colore','fossili')\npc <- prcomp(d[v],center=TRUE,scale.=TRUE)\nquota <- pc$sdev^2/sum(pc$sdev^2)\nround(quota,3)\nround(pc$rotation[,1:2],3)\nhead(predict(pc,d[v]))")
p('L’oggetto PCA conserva la trasformazione',
'''La chiamata a prcomp specifica centratura e ridimensionamento, evitando che le impostazioni predefinite decidano implicitamente la geometria dell’analisi. L’oggetto risultante conserva medie, scale, rotazione e scores, così che nuovi campioni possano essere proiettati mediante predict. Le quote di varianza si ricavano dai quadrati di sdev. Per documentare il risultato si esportano le coordinate insieme agli identificativi e si riportano, nella figura, le quote associate agli assi mostrati.''',codice=c,richiamo='Il risultato riproducibile comprende le trasformazioni che definiscono lo spazio delle componenti.',fonti='R: prcomp',origine='M08:39–45,47–55,97–101')

m.sezione_nuova('Partizioni mediante K-means')
p('K-means minimizza la dispersione entro i gruppi',
'''Fissato un numero k, K-means cerca una partizione dei campioni che renda piccola la somma delle distanze quadratiche dai rispettivi centroidi. Il centroide è la media delle righe assegnate al gruppo, per cui la funzione obiettivo dipende dalla scala e privilegia aggregazioni compatte. Il numero di gruppi viene fornito all’algoritmo e scelto confrontando stabilità, dimensioni e plausibilità delle soluzioni.''',formula=r'W(\mathcal C)=\sum_{g=1}^k\sum_{i\in C_g}\|\mathbf z_i-\boldsymbol\mu_g\|^2\\ \boldsymbol\mu_g=\frac1{|C_g|}\sum_{i\in C_g}\mathbf z_i',tikz=d('D07',r'\draw[Classical,fill=Classical!5] (2,2.1) ellipse (1.35 and 1.4);\draw[Quantum,fill=Quantum!5] (5.5,4) ellipse (1.3 and 1.4);'+''.join(rf'\fill[Classical] ({x},{y}) circle (2pt);\draw[Classical!50] ({x},{y})--(2,2.1);' for x,y in [(1.3,1.6),(2.4,1.5),(1.7,2.8),(2.6,2.5)])+''.join(rf'\fill[Quantum] ({x},{y}) circle (2pt);\draw[Quantum!50] ({x},{y})--(5.5,4);' for x,y in [(4.8,3.5),(5.9,3.5),(5.3,4.7),(6,4.3)])+n(2,2.1,r'$\times$')+n(5.5,4,r'$\times$')+n(3.7,5.9,'Croci: centroidi; segmenti: scarti.',w=6.8,size=11)),richiamo='La funzione obiettivo deve essere interpretata nella scala sulla quale viene minimizzata.',origine='M08:56–58,63–65')
p('Assegnazione e aggiornamento spiegano la ricerca',
'''Un procedimento alternato assegna ciascun campione al centroide più vicino e ricalcola i centroidi come medie dei gruppi ottenuti. Ogni passaggio riduce o conserva la funzione obiettivo, ma può condurre a un minimo locale dipendente dall’inizializzazione. Questa costruzione illustra l’algoritmo di Lloyd; l’impostazione predefinita di kmeans in R utilizza Hartigan–Wong, che ricerca la stessa funzione obiettivo mediante aggiornamenti differenti. Ripetere gli avvii consente di esplorare più soluzioni senza garantire l’ottimo globale.''',formula=r'g_i\leftarrow\arg\min_g\|\mathbf z_i-\boldsymbol\mu_g\|^2\\ \boldsymbol\mu_g\leftarrow\operatorname{media}_{i:g_i=g}(\mathbf z_i)',tikz=d('D08',rect(.8,.7,6.6,2.1)+n(3.7,1.4,'Assegnare ai centroidi più vicini',w=5.2,size=11)+a(3.7,2.3,3.7,3)+rect(.8,3.2,6.6,4.6,'Quantum')+n(3.7,3.9,'Ricalcolare le medie dei gruppi',w=5.2,size=11)+r'\draw[arr] (6.8,3.9)--(7.2,3.9)--(7.2,1.4)--(6.8,1.4);'+n(3.7,5.6,'Iterare finché le assegnazioni si stabilizzano.',w=6.8,size=11)),richiamo='Il seme rende ripetibile una ricerca; gli avvii multipli ne migliorano l’esplorazione.',origine='M08:59–60,87')
p('Dallo spazio completo al piano principale',
'''La partizione del laboratorio viene stimata sulle otto variabili standardizzate e successivamente mostrata nel piano principale. Un confine apparentemente ambiguo nella figura può dipendere da componenti escluse dalla rappresentazione, mentre colori nettamente separati descrivono soltanto la proiezione scelta. Il confronto con centroidi e profili consente di comprendere quali proprietà sostengano i gruppi. In presenza di forme allungate, densità differenti o strutture non convesse, la somma quadratica può produrre suddivisioni poco aderenti alla domanda geologica.''',figura='M08/F09',didascalia='K-means con k = 3 e 50 avvii sulle otto colonne standardizzate. La PCA viene usata esclusivamente per la rappresentazione.',formula=r'\text{stima in }\mathbb R^8\quad\longrightarrow\quad\text{figura in }\mathbb R^2',richiamo='La dimensione del grafico e la dimensione dello spazio di stima devono essere indicate separatamente.',origine='M08:61–65')
c=estratto('M08','kmeans',"d <- read.csv('dati/rocce_simulate.csv')\nv <- c('SiO2','CaO','MgO','FeO',\n       'densita','grana_mm','colore','fossili')\nZ <- scale(d[v])\nset.seed(808)\nk <- kmeans(Z,centers=3,nstart=50)\nk$size\nk$tot.withinss\nround(k$centers,2)")
p('La riproducibilità richiede più del numero dei gruppi',
'''Il codice conserva variabili, trasformazione, seme e numero di avvii, così che la ricerca possa essere ripetuta nelle stesse condizioni. Le dimensioni dei gruppi permettono di riconoscere eventuali partizioni sostenute da pochissimi casi, mentre i centroidi standardizzati ne descrivono i profili. Ripetere la procedura con semi diversi verifica la sensibilità alla ricerca numerica; modificare una variabile o la standardizzazione valuta invece la sensibilità della domanda quantitativa posta ai dati.''',codice=c,richiamo='Instabilità numerica e sensibilità alla definizione delle variabili richiedono verifiche distinte.',origine='M08:60,63,87–88,97–99')

m.sezione_nuova('Numero dei gruppi e silhouette')
p('WSS e numero dei gruppi',
'''Aumentando k, l’ottimo teorico della somma quadratica interna può soltanto diminuire o restare invariato, poiché una soluzione con più gruppi può suddividere una partizione precedente. La riduzione ottenuta deve essere valutata rispetto all’aumento di complessità. Il cosiddetto gomito identifica visivamente un cambio di pendenza, ma può risultare sfumato o dipendere dall’intervallo di k considerato. Se gli avvii conducono a minimi locali differenti, le WSS calcolate possono inoltre discostarsi dalla monotonia dell’ottimo teorico.''',formula=r'W^*_{k+1}\leq W^*_k,\qquad W^*_n=0',figura='M08/F05',didascalia='WSS per k da 2 a 7, con 50 avvii per ogni soluzione. La diminuzione deve essere confrontata con stabilità e interpretazione.',richiamo='Il gomito fornisce un criterio esplorativo, la cui evidenza può essere ambigua.',origine='M08:66–68,73–75')
p('La silhouette confronta coesione e separazione',
'''Per un campione i, a è la distanza media dagli altri membri del suo gruppo, mentre b è la minore distanza media verso un gruppo diverso. La silhouette combina queste quantità in un indice compreso fra meno uno e uno: valori positivi elevati indicano maggiore vicinanza al gruppo assegnato, valori prossimi a zero descrivono confini incerti e valori negativi suggeriscono un’assegnazione discutibile rispetto alla metrica. Per gruppi composti da un solo elemento si adotta convenzionalmente silhouette nulla.''',formula=r's_i=\frac{b_i-a_i}{\max(a_i,b_i)},\qquad -1\leq s_i\leq1',tikz=d('D09',rect(.3,1,3.2,4.8)+n(1.75,1.5,'Gruppo assegnato',w=2.5,size=10.8)+rect(4.2,1,7.1,4.8,'Quantum')+n(5.65,1.5,'Altro gruppo',w=2.5,size=10.8)+n(1.1,3,r'$i$')+a(1.4,3,2.6,3)+n(2.2,3.7,r'$a_i$')+a(1.4,2.6,5.8,2.6,'Quantum')+n(4,2.15,r'$b_i$')+n(3.7,5.6,'Le distanze sono medie verso gruppi.',w=6.8,size=11)),richiamo='Una silhouette media favorevole può nascondere singoli campioni con assegnazione incerta.',origine='M08:69–71')
p('La scelta di k richiede confronti convergenti',
'''Il confronto delle silhouette medie offre un criterio complementare alla riduzione della WSS, perché considera la separazione rispetto alla coesione dei gruppi. Nel caso sintetico le strutture sono state generate in modo relativamente netto; nei dati reali il massimo può essere debole oppure favorire una suddivisione troppo grossolana per l’uso previsto. La scelta viene quindi documentata insieme ad almeno una soluzione alternativa, alle dimensioni dei gruppi e all’ispezione dei casi con silhouette bassa.''',figura='M08/F06',didascalia='Silhouette media sulle stesse distanze standardizzate impiegate per il confronto dei gruppi.',richiamo='Una partizione va motivata attraverso indici, stabilità, profili e finalità dell’analisi.',origine='M08:72–75,100')

m.sezione_nuova('Gerarchie e criterio di Ward')
p('Il criterio di fusione di Ward',
'''Il clustering agglomerativo parte da gruppi costituiti da un solo campione e procede mediante fusioni irreversibili. Il criterio di Ward sceglie, a ogni passaggio, la fusione che produce il minore incremento della dispersione quadratica interna. Tale incremento dipende dalla distanza fra centroidi e dalle numerosità dei due gruppi, come si ricava decomponendo gli scarti rispetto al nuovo centroide comune. La procedura costruisce una gerarchia, dalla quale si ricavano partizioni mediante tagli a livelli differenti.''',formula=r'\Delta W(A,B)=\frac{n_A n_B}{n_A+n_B}\|\bar{\mathbf z}_A-\bar{\mathbf z}_B\|^2',tikz=d('D10',rect(.4,.8,3.2,2.3)+n(1.8,1.55,r'$A,\ n_A,\ \bar{\mathbf z}_A$',w=2.5,size=11)+rect(4.2,.8,7,2.3,'Quantum')+n(5.6,1.55,r'$B,\ n_B,\ \bar{\mathbf z}_B$',w=2.5,size=11)+a(1.8,2.5,3,3.4)+a(5.6,2.5,4.4,3.4,'Quantum')+rect(1.4,3.6,6,5.1)+n(3.7,4.35,r'$A\cup B$',w=4)+n(3.7,5.8,'La fusione aumenta la WSS di ΔW.',w=6.8,size=11)),richiamo='Il criterio di fusione comprende sia le distanze fra centroidi sia le numerosità.',origine='M08:76–78')
p('Le altezze del dendrogramma di Ward',
'''Con distanze euclidee fornite a hclust e metodo ward.D2, R eleva internamente al quadrato le dissimilarità durante gli aggiornamenti. Le altezze restituite corrispondono alla radice di due volte l’incremento della WSS, relazione verificata nello script per ogni fusione del dataset. Il taglio tratteggiato produce tre gruppi. La posizione orizzontale delle foglie serve a disegnare i rami senza incroci e può cambiare mediante rotazioni, senza modificare la struttura delle fusioni.''',formula=r'\texttt{hclust(dist(Z), method="ward.D2")}\\ h_r=\sqrt{2\,\Delta W_r}',figura='M08/F07',didascalia='Dendrogramma Ward.D2. L’asse orizzontale riporta posizioni delle foglie, non distanze fra campioni consecutivi.',richiamo='Fornire distanze già elevate al quadrato a ward.D2 cambierebbe la geometria del criterio.',fonti='R: hclust',origine='M08:79–85')
c=estratto('M08','ward',"d <- read.csv('dati/rocce_simulate.csv')\nv <- c('SiO2','CaO','MgO','FeO',\n       'densita','grana_mm','colore','fossili')\nZ <- scale(d[v])\nh <- hclust(dist(Z),method='ward.D2')\ng <- cutree(h,k=3)\nset.seed(808)\nk <- kmeans(Z,3,nstart=50)$cluster\ntable(Kmeans=k,Ward=g)")
p('Confrontare partizioni e allineare le etichette',
'''I numeri assegnati ai gruppi sono etichette prive di ordinamento. Due partizioni identiche possono quindi apparire differenti se si confrontano direttamente i vettori numerici, mentre una tabella di contingenza rende visibile la corrispondenza. Un confronto indipendente dai nomi considera le coppie di campioni che risultano nello stesso gruppo. Le discord anze fra Ward e K-means meritano un esame dei profili e dei casi di confine, poiché i metodi cercano strutture secondo vincoli diversi.'''.replace('discord anze','discordanze'),formula=r'A_{ih}=\mathbf1\{g_i=g_h\}',codice=c,richiamo='Le etichette devono essere allineate oppure confrontate attraverso appartenenze congiunte.',origine='M08:83–85,93')

m.sezione_nuova('Robustezza e significato geologico')
p('I profili collegano i gruppi alle proprietà misurate',
'''Le medie standardizzate dei gruppi mostrano quali proprietà siano relativamente elevate o ridotte rispetto al campione complessivo. La lettura congiunta dei profili permette di motivare un nome descrittivo e di riconoscere eventuali contrasti dominati da una sola misura. Per una conclusione geologica occorre poi tornare alle unità originarie e ai singoli campioni, poiché un centroide può combinare valori che nessun individuo possiede. I nomi delle litologie generatrici restano un riferimento didattico del simulatore.''',figura='M08/F08',didascalia='Centroidi standardizzati.',richiamo='Un gruppo matematico acquista significato mediante proprietà, campioni e informazioni indipendenti.',origine='M08:63,90–92,99')
p('Le diverse fonti di instabilità della partizione',
'''La ripetizione degli avvii esamina la ricerca dell’algoritmo, mentre ricampionare individui o perturbare misure valuta altre fonti di variabilità. Per confrontare le soluzioni ricampionate si può registrare quanto spesso una coppia di individui, quando entrambi siano presenti, venga assegnata allo stesso gruppo. Tale frequenza descrive la stabilità rispetto allo schema adottato e deve essere interpretata insieme alla numerosità delle occasioni di confronto. Variare una colonna ridondante o una scala può rivelare dipendenze strutturali della partizione.''',formula=r'\widehat\pi_{ih}=\frac{\sum_b I_{ih}^{(b)}\mathbf1\{g_i^{(b)}=g_h^{(b)}\}}{\sum_b I_{ih}^{(b)}}',destra='I indica che entrambi i campioni sono presenti nella replica. Nel bootstrap alcune righe compaiono più volte: l’implementazione deve specificare come rappresentare duplicati e casi assenti. Una frequenza elevata è riferita alle perturbazioni effettivamente introdotte.',richiamo='Lo schema di perturbazione stabilisce quale stabilità venga misurata.',origine='M08:87–89,92–95')
p('L’indipendenza dell’evidenza di validazione',
'''L’accordo con le etichette del simulatore conferma che la procedura può recuperare la struttura costruita nell’esperimento, ma lascia aperta la trasferibilità a campioni reali. Densità, colore e granulometria, se già usati nella distanza, contribuiscono a descrivere i gruppi e non costituiscono una verifica esterna. Una valutazione geologica può invece coinvolgere osservazioni petrografiche indipendenti, contesti stratigrafici o nuovi campioni, purché la relazione con le variabili iniziali sia resa esplicita.''',tikz=d('D11',rect(.4,.7,3.3,2.6)+n(1.85,1.65,'Misure usate nella partizione',w=2.5,size=11)+rect(4.1,.7,7,2.6,'Quantum')+n(5.55,1.65,'Evidenza acquisita separatamente',w=2.5,size=11)+a(1.85,2.8,2.7,4)+a(5.55,2.8,4.7,4,'Quantum')+n(3.7,4.7,'Confronto scientifico motivato',w=5.5)+n(3.7,5.8,'Le fonti dell’informazione restano identificabili.',w=6.8,size=10.8)),richiamo='La validità geologica richiede evidenza che ecceda il criterio utilizzato per costruire i gruppi.',origine='M08:91,94–95,110')

m.sezione_nuova('Laboratorio e riferimenti')
p('La consegna conserva campioni, alternative e limiti',
'''Il laboratorio richiede una matrice con otto variabili dichiarate, una PCA con quote di varianza, il confronto fra k da due a sette, una partizione K-means e una gerarchia di Ward. Una tabella finale mantiene identificativo, coordinate principali e appartenenze ai gruppi, così che ogni risultato possa essere ricondotto al campione. La relazione discute una soluzione alternativa e almeno un caso ambiguo, motivando trasformazioni, esclusioni e limiti della simulazione. La permutazione delle righe deve preservare l’interpretazione, una volta riallineati gli identificativi.''',formula=r'\text{ID}\ \leftrightarrow\ (\text{scores},\ \text{gruppi},\ \text{misure})',destra='Verifica proposta: ricostruire Z con tutte le componenti e controllare l’errore numerico; ricostruirla con due componenti e confrontare la somma degli scarti quadratici con gli autovalori omessi. Gli script delle figure eseguono entrambi i controlli e verificano anche le altezze di Ward.',richiamo='Una figura interpretabile deve essere accompagnata dalla trasformazione e dai risultati per campione.',origine='M08:96–107')
p('Riferimenti per geometria e implementazione',
'''La documentazione di prcomp precisa la decomposizione ai valori singolari, il divisore della varianza e l’arbitrarietà dei segni; le pagine di kmeans e hclust definiscono algoritmi, parametri e convenzioni delle distanze. Per la geometria multivariata si può consultare Mardia, Kent e Bibby, Multivariate Analysis; per il trattamento delle composizioni, Aitchison, The Statistical Analysis of Compositional Data. La distinzione fra le convenzioni di Ward è discussa da Murtagh e Legendre nel loro confronto degli algoritmi agglomerativi.''',destra='Documentazione R: prcomp, kmeans, hclust e silhouette del pacchetto cluster. Gli indirizzi completi, le versioni dei pacchetti e le verifiche numeriche sono raccolti nei materiali del corso. Tutte le figure di questo modulo derivano dai dati sintetici allegati.',richiamo='Le convenzioni del software devono essere dichiarate quando modificano il significato dei risultati.',fonti='R; Mardia et al.; Aitchison',origine='M08:108–109')
m.salva()
